namespace sv_e053cfc491f4468ba3d6b928cdb275ca.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Components subscribe to OnChange to react when any other component mutates the theme.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Subscribers should call StateHasChanged (or InvokeAsync) to re-render.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island that lives in the static layout header and reacts to theme changes *@
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<span class="badge" style="background-color: @ThemeSvc.AccentColor;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="SelectedAccentColor" @bind:event="oninput" />
</div>

<p>
    Current: <strong>@ThemeSvc.Theme</strong> /
    <span style="color: @ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
</p>

@code {
    private Services.ThemeMode SelectedTheme
    {
        get => ThemeSvc.Theme;
        set => ThemeSvc.Theme = value;
    }

    private string SelectedAccentColor
    {
        get => ThemeSvc.AccentColor;
        set => ThemeSvc.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleChanged;
    }
}

